<script setup>
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import Errors from '../../Components/Errors.vue';
defineProps({googleEnabled:{type:Boolean,default:false}});
const page=usePage();
const form=useForm({name:'',email:'',password:'',password_confirmation:''});
const submit=()=>form.post('/register',{onFinish:()=>form.reset('password','password_confirmation')});
</script>
<template><Head title="Create your space"/><div class="auth-shell"><section class="auth-story"><div class="brand"><span class="brand-symbol">v.</span>vocamilo</div><div><span class="pill">A SPACE FOR YOUR WORDS</span><h1>Curiosity<br>looks good<br>on you.</h1><p>Collect what matters. Practice what you want to remember.</p></div><div class="auth-decoration">Your learning starts here.</div></section><main class="auth-form"><div class="eyebrow">LET'S GET STARTED</div><h1>Create your space.</h1><p class="muted">A personal word pool, ready to grow.</p><p v-if="page.props.errors?.google" class="notice error" role="alert">{{page.props.errors.google}}</p><a v-if="googleEnabled" href="/auth/google/redirect" class="button secondary google-signin">Continue with Google</a><p v-if="googleEnabled" class="muted small">Or continue with your email and password</p><form @submit.prevent="submit"><Errors :errors="form.errors"/><label>Name<input v-model="form.name" required maxlength="100" autocomplete="name"/></label><label>Email<input v-model="form.email" type="email" required autocomplete="email"/></label><label>Password (at least 10 characters)<input v-model="form.password" type="password" required minlength="10" autocomplete="new-password"/></label><label>Confirm password<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"/></label><button class="button" :disabled="form.processing">{{form.processing?'Creating…':'Create account →'}}</button></form><p class="auth-switch">Already learning here? <Link href="/login">Sign in</Link></p></main></div></template>
